83	    /**
84	     * HTTP header carrying the client-supplied idempotency key for the create endpoint. When a
85	     * create repeats with a key already seen, the originally created owner is returned instead of
86	     * creating a duplicate.
87	     */
88	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
89	
90	    /**
91	     * Remembers, per seen {@code Idempotency-Key}, the id of the owner that key's create produced,
92	     * so a repeat create with the same key can return the originally created owner rather than
93	     * persisting a duplicate. Shared across requests, hence concurrency-safe.
94	     */
95	    private static final Map<String, Integer> IDEMPOTENT_CREATES = new ConcurrentHashMap<>();
96	
