370	    /**
371	     * Applies the intake rules a newly submitted owner must satisfy before it is persisted.
372	     * The address is normalized in place (so a required-field check that follows rejects an
373	     * address blank after normalization), the required fields are checked, the telephone and
374	     * email are normalized in place, and the resulting owner is rejected when its derived
375	     * identity key already belongs to another owner. Each rule
376	     * signals a violation by throwing, which the exception advice renders as the matching 4xx
377	     * response; when the method returns normally {@code ownerFieldsDto} is normalized and ready
378	     * to be mapped and saved.
379	     *
380	     * @param ownerFieldsDto the submitted owner fields, normalized in place
381	     */
382	    private void prepareNewOwner(OwnerFieldsDto ownerFieldsDto, LocalDate registrationDate) {
383	        applyAddress(ownerFieldsDto);
384	        validateRequiredFields(ownerFieldsDto);
385	        ownerFieldsDto.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
386	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
387	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
388	        rejectDuplicateIdentity(ownerFieldsDto);
389	        rejectCityAtCapacity(ownerFieldsDto.getCity());
390	        rejectDailyLimitExceeded(registrationDate);
391	    }
392	
393	    /**
394	     * Applies an owner's address to the submitted fields, normalizing it in place into the
395	     * canonical form stored and returned for the owner. This is the single intake step that owns
396	     * how a submitted address becomes an owner's stored address: it delegates every transform to
397	     * {@link #normalizeAddress(String)}, the single definition of address normalization, and writes
398	     * the results back onto {@code ownerFieldsDto}.
399	     *
400	     * <p>The structured fields are preferred when supplied: when a non-blank {@code addressLine1}
401	     * is present the two structured lines are normalized in place and the flat {@code address} is
402	     * (re)composed from them — the normalized {@code addressLine1}, with a single space and the
403	     * normalized {@code addressLine2} appended only when an {@code addressLine2} was supplied — so
404	     * every rule that later reads {@code address} sees the structured value. When no structured
405	     * {@code addressLine1} is supplied the flat {@code address} is normalized in place, preserving
406	     * backward compatibility.
407	     *
408	     * <p>It runs ahead of {@link #validateRequiredFields(OwnerFieldsDto)} so an address that is
409	     * blank after normalization in either form is rejected by the required-field check that
410	     * follows. Isolating the step here keeps {@link #prepareNewOwner(OwnerFieldsDto, LocalDate)} a
411	     * list of named intake steps and gives address handling one place to grow.
412	     *
413	     * @param ownerFieldsDto the submitted owner fields, whose address is normalized in place
414	     */
415	    private void applyAddress(OwnerFieldsDto ownerFieldsDto) {
416	        String line1 = ownerFieldsDto.getAddressLine1();
417	        if (line1 != null && !line1.isBlank()) {
418	            String normalizedLine1 = normalizeAddress(line1);
419	            ownerFieldsDto.setAddressLine1(normalizedLine1);
420	            String line2 = ownerFieldsDto.getAddressLine2();
421	            if (line2 != null && !line2.isBlank()) {
422	                String normalizedLine2 = normalizeAddress(line2);
423	                ownerFieldsDto.setAddressLine2(normalizedLine2);
424	                ownerFieldsDto.setAddress(normalizedLine1 + " " + normalizedLine2);
425	            } else {
426	                ownerFieldsDto.setAddressLine2(null);
427	                ownerFieldsDto.setAddress(normalizedLine1);
428	            }
429	        } else {
430	            ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
431	        }
432	    }
433	
434	    /**
435	     * Determines the effective registration date for a newly submitted owner, adjusted so it always
436	     * falls on a business day. The date supplied on the request is used when present, otherwise the
437	     * server's current date is used. When that effective date lands on a Saturday, Sunday or listed
438	     * public holiday it is rolled forward to the next non-holiday business day; a non-holiday weekday
439	     * is left unchanged. This single adjusted date
440	     * is what gets stored as {@code registrationDate} and is what every value derived from it (the
441	     * membership number's year segment, the per-day create limit) is computed against.
442	     *
443	     * A supplied registration date later than the server's current date is rejected with an
444	     * {@link InvalidFieldsException}, which the exception advice renders as a 400 Bad Request.
445	     *
446	     * @param ownerFieldsDto the submitted owner fields, which may carry a registration date
447	     * @return the effective registration date rolled forward to the next business day
448	     */
449	    private LocalDate effectiveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
450	        LocalDate supplied = ownerFieldsDto.getRegistrationDate();
451	        if (supplied != null && supplied.isAfter(LocalDate.now())) {
452	            throw new InvalidFieldsException(List.of("registrationDate"));
453	        }
454	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
455	        return toBusinessDay(effective);
456	    }
457	
458	    /**
459	     * The fixed public holidays the business-day roll skips. A date landing on any of these is
460	     * advanced, along with weekends, until it reaches the next non-holiday business day.
461	     */
462	    private static final java.util.Set<LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
463	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
464	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
465	        LocalDate.parse("2026-12-28"));
466	
467	    /**
468	     * Rolls a date forward to the next business day: a Saturday, Sunday or listed public holiday is
469	     * advanced one day at a time until it reaches a weekday that is not a public holiday, while a
470	     * date already on such a business day is returned unchanged.
471	     *
472	     * @param date the date to adjust
473	     * @return the same date when it is a non-holiday weekday, otherwise the next such business day
474	     */
475	    private LocalDate toBusinessDay(LocalDate date) {
476	        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
477	                || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
478	                || PUBLIC_HOLIDAYS.contains(date)) {
479	            date = date.plusDays(1);
480	        }
481	        return date;
482	    }
483	
484	    /**
485	     * The maximum number of owners that may be created on a single day. Once this many owners
486	     * already carry today's {@code registrationDate}, no further owner may be created today.
487	     */
488	    private static final long DAILY_OWNER_LIMIT = 100L;
489	
490	    /**
491	     * Rejects a new owner when {@link #DAILY_OWNER_LIMIT} or more owners already carry the given
492	     * adjusted business-day {@code registrationDate}. The count is taken against the same adjusted
493	     * date the new owner would be stored with, so owners are capped per business day. When the limit
494	     * has been reached a {@link DailyOwnerLimitExceededException} is thrown, which the exception
495	     * advice renders as a 429 Too Many Requests response.
496	     *
497	     * @param registrationDate the adjusted business-day registration date of the owner being created
498	     */
499	    private void rejectDailyLimitExceeded(LocalDate registrationDate) {
500	        if (countOwnersRegisteredOn(registrationDate) >= DAILY_OWNER_LIMIT) {
501	            throw new DailyOwnerLimitExceededException(registrationDate);
502	        }
503	    }
504	
505	    /**
506	     * Counts the existing owners whose adjusted business-day {@code registrationDate} equals the
507	     * given date. This is the single definition of the per-day owner count, shared by the per-day
508	     * create limit ({@link #rejectDailyLimitExceeded(LocalDate)}) and the bulk-signup warning
509	     * ({@link #bulkSignupWarning(LocalDate)}), so both accumulate owners against a day identically.
510	     *
511	     * @param registrationDate the adjusted business-day registration date to count owners against
512	     * @return the number of existing owners carrying that registration date
513	     */
514	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
515	        return this.clinicService.findAllOwners().stream()
516	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
517	            .count();
518	    }
519	
520	    /**
