638	     * @param owner the owner being created, already carrying its normalized telephone and postcode
639	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
640	     */
641	    private void applyPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
642	        owner.setPossibleDuplicate(false);
643	        owner.setPossibleDuplicateOf(null);
644	        if (sharesHousehold(ownerFieldsDto)) {
645	            return;
646	        }
647	        findPossibleDuplicate(owner).ifPresent(existing -> {
648	            owner.setPossibleDuplicate(true);
649	            owner.setPossibleDuplicateOf(existing.getId());
650	        });
651	    }
