703	    /**
704	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets
705	     * are stripped. When a leading {@code '+'} and country code are present they are kept as
706	     * given; otherwise the country code {@code '+61'} is assumed and a single leading
707	     * {@code '0'} is dropped from the national digits. The result must be a {@code '+'}
708	     * followed by 8 to 15 digits. The normalized E.164 value is what gets stored and returned.
709	     * When the value cannot form a valid E.164 number an {@link InvalidFieldsException} is
710	     * thrown, which the exception advice renders as a 400 response naming the {@code telephone}
711	     * field. For example {@code "0412 345 678"} becomes {@code "+61412345678"}.
712	     *
713	     * @param telephone the submitted telephone value
714	     * @return the normalized E.164 telephone
715	     */
716	    private String normalizeTelephone(String telephone) {
717	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
718	        String e164;
719	        if (cleaned.startsWith("+")) {
720	            e164 = "+" + cleaned.substring(1);
721	        } else {
722	            String national = cleaned;
723	            if (national.startsWith("0")) {
724	                national = national.substring(1);
725	            }
726	            e164 = "+61" + national;
727	        }
728	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
729	            throw new InvalidFieldsException(List.of("telephone"));
730	        }
731	        validateNationalNumberLength(e164);
732	        return e164;
733	    }
734	
735	    /**
736	     * Validates the national-number length of an already syntactically valid E.164 telephone
737	     * against its country code. When the number carries a country code this application recognizes
738	     * (see {@link Owner#countryCodeOf(String)}) the digits following that code must have exactly the
739	     * length that code admits ({@code '+61'} => 9 national digits, {@code '+1'} => 10, see
740	     * {@link Owner#nationalNumberLength(String)}). When the country code is recognized but the
741	     * national number is the wrong length an {@link InvalidFieldsException} is thrown, which the
742	     * exception advice renders as a 400 response naming the {@code telephone} field. A country code
743	     * that is not recognized carries no per-country length rule and is left to the general
744	     * 8-to-15-digit E.164 check.
745	     *
746	     * @param e164 the normalized E.164 telephone (a {@code '+'} followed by digits)
747	     */
748	    private void validateNationalNumberLength(String e164) {
749	        String countryCode = Owner.countryCodeOf(e164);
750	        if (countryCode == null) {
751	            return;
752	        }
753	        int nationalLength = e164.length() - 1 - countryCode.length();
754	        if (nationalLength != Owner.nationalNumberLength(countryCode)) {
755	            throw new InvalidFieldsException(List.of("telephone"));
756	        }
757	    }
