759	    /**
760	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
761	     * and a domain containing at least one dot, none of the parts holding whitespace or a
762	     * second {@code @}.
763	     */
764	    private static final java.util.regex.Pattern EMAIL_PATTERN =
765	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
766	
767	    /**
768	     * Disposable email domains an owner may not register with. An email whose domain (compared
769	     * case-insensitively) is one of these is rejected, since it identifies a throwaway mailbox.
770	     */
771	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
772	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
773	
774	    /**
775	     * Normalizes an optional owner email. An email is optional, so a {@code null} value is
776	     * accepted and returned unchanged. When present it must be a syntactically valid address
777	     * whose domain is not on the disposable-domain blocklist (see
778	     * {@link #DISPOSABLE_EMAIL_DOMAINS}); the value is stored and returned lower-cased. When
779	     * present but syntactically invalid or on a disposable domain an
780	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
781	     * response naming the {@code email} field.
782	     *
783	     * @param email the submitted email value, or {@code null} when omitted
784	     * @return the lower-cased email, or {@code null} when none was supplied
785	     */
786	    private String normalizeEmail(String email) {
787	        if (email == null) {
788	            return null;
789	        }
790	        String trimmed = email.trim();
791	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
792	            throw new InvalidFieldsException(List.of("email"));
793	        }
794	        String domain = trimmed.substring(trimmed.lastIndexOf('@') + 1).toLowerCase(java.util.Locale.ROOT);
795	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
796	            throw new InvalidFieldsException(List.of("email"));
797	        }
798	        return canonicalEmail(trimmed);
799	    }
