801	    /**
802	     * Reduces an email to the canonical form used both to store it and to compare it against
803	     * other owners' emails: surrounding whitespace is trimmed and the value is lower-cased. A
804	     * {@code null} email (none was supplied) canonicalizes to {@code null}. Unlike
805	     * {@link #normalizeEmail(String)} no validation is performed, so this can be applied to a
806	     * value read back off an existing owner without risk of rejecting it. This is the single
807	     * definition of email identity: two emails denote the same address exactly when they
808	     * canonicalize to the same value, so an email stored via {@link #normalizeEmail(String)} and
809	     * an email already on an existing owner can be compared for equality after both pass through
810	     * here. For example {@code "  Jane@Example.COM "} canonicalizes to {@code "jane@example.com"}.
811	     *
812	     * @param email the email to canonicalize, or {@code null} when none was supplied
813	     * @return the trimmed, lower-cased email, or {@code null} when {@code email} is {@code null}
814	     */
815	    private String canonicalEmail(String email) {
816	        if (email == null) {
817	            return null;
818	        }
819	        return email.trim().toLowerCase(java.util.Locale.ROOT);
820	    }
