36	import org.springframework.web.bind.annotation.ControllerAdvice;
37	import org.springframework.web.bind.annotation.ExceptionHandler;
38	import org.springframework.web.bind.annotation.ResponseBody;
39	
40	/**
41	 * Global Exception handler for REST controllers.
42	 * <p>
43	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
44	 *
45	 * @author Vitaliy Fedoriv
46	 * @author Alexander Dudkin
47	 */
48	@ControllerAdvice
49	public class ExceptionControllerAdvice {
50	
51	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
52	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
53	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
54	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
55	    private static final String ERROR_DUPLICATE_IDENTITY = "An owner with the given identity already exists";
56	    private static final String ERROR_CITY_AT_CAPACITY = "The owner's city already contains the maximum number of owners";
57	    private static final String ERROR_DAILY_LIMIT_EXCEEDED = "The maximum number of owners has already been created today";
58	
59	    /**
60	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
61	     * class.
62	     *
63	     * @param e     Object referring to the thrown exception.
64	     * @param status HTTP response status.
65	     * @param url URL request.
66	     */
67	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
68	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
69	        problemDetail.setType(URI.create(url.toString()));
70	        problemDetail.setTitle(e.getClass().getSimpleName());
71	        problemDetail.setDetail(detail);
72	        problemDetail.setProperty("timestamp", Instant.now());
73	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
74	        return problemDetail;
75	    }
76	
77	    /**
78	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
79	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
80	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
81	     * would catch it and report an authorization failure as a 500.
82	     *
83	     * @param e The {@link AccessDeniedException} to propagate
84	     * @throws AccessDeniedException always
85	     */
86	    @ExceptionHandler(AccessDeniedException.class)
87	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
88	        throw e;
89	    }
90	
91	    /**
92	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
93	     *
94	     * @param e The {@link Exception} to be handled
95	     * @param request {@link HttpServletRequest} object referring to the current request.
96	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
97	     */
98	    @ExceptionHandler(Exception.class)
99	    @ResponseBody
100	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
101	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
102	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
103	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
104	        return ResponseEntity.status(status).body(detail);
105	    }
106	
107	    /**
108	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
109	     * method returns a 404 Not Found status if an entity does not exist.
110	     *
111	     * @param e The {@link DataIntegrityViolationException} to be handled
112	     * @param request {@link HttpServletRequest} object referring to the current request.
113	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
114	     */
115	    @ExceptionHandler(DataIntegrityViolationException.class)
116	    @ResponseBody
117	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
118	        logger.warn("Data integrity violation at {} {}: {}",
119	            request.getMethod(),
120	            request.getRequestURI(),
121	            e.getMessage());
122	        logger.debug("Data integrity violation stacktrace", e);
123	        HttpStatus status = HttpStatus.NOT_FOUND;
124	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
125	        return ResponseEntity.status(status).body(detail);
126	    }
127	
128	    /**
129	     * Handles exception thrown by Bean Validation on controller methods parameters
130	     *
131	     * @param e The {@link MethodArgumentNotValidException} to be handled
132	     * @param request {@link HttpServletRequest} object referring to the current request.
133	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
134	     */
135	    @ExceptionHandler(MethodArgumentNotValidException.class)
136	    @ResponseBody
137	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
138	        HttpStatus status = HttpStatus.BAD_REQUEST;
139	        BindingResult bindingResult = e.getBindingResult();
140	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
141	        if (bindingResult.hasErrors()) {
142	            logger.debug("Validation error at {} {}: {}",
143	                request.getMethod(),
144	                request.getRequestURI(),
145	                bindingResult.getFieldErrors());
146	            detail.setProperty("schemaValidationErrors", schemaValidationErrors(bindingResult));
147	            detail.setProperty("errors", bindingResult.getFieldErrors().stream()
148	                .map(FieldError::getField)
149	                .distinct()
150	                .toList());
151	        }
152	        return ResponseEntity.status(status).body(detail);
153	    }
154	
155	    /**
156	     * Handles the {@link FieldValidationException} family thrown when a request omits or leaves
157	     * blank a required field ({@link RequiredFieldsMissingException}) or supplies a field whose
158	     * value is present but fails a business rule ({@link InvalidFieldsException}). Returns a 400
159	     * Bad Request whose {@code errors} property lists the name of each offending field.
160	     *
161	     * @param e The {@link FieldValidationException} to be handled
162	     * @param request {@link HttpServletRequest} object referring to the current request.
163	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
164	     */
165	    @ExceptionHandler(FieldValidationException.class)
166	    @ResponseBody
167	    public ResponseEntity<ProblemDetail> handleFieldValidationException(FieldValidationException e, HttpServletRequest request) {
168	        HttpStatus status = HttpStatus.BAD_REQUEST;
169	        logger.debug("Field validation failed at {} {}: {}",
170	            request.getMethod(),
171	            request.getRequestURI(),
172	            e.getFields());
173	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
174	        detail.setProperty("errors", e.getFields());
175	        return ResponseEntity.status(status).body(detail);
176	    }
177	
178	    /**
179	     * Handles {@link DuplicateIdentityException} thrown when a request tries to create an owner
180	     * whose derived identity key (normalized telephone, email and household identifier) is already
181	     * used by another owner. Returns a 409 Conflict.
182	     *
183	     * @param e The {@link DuplicateIdentityException} to be handled
184	     * @param request {@link HttpServletRequest} object referring to the current request.
185	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
186	     */
187	    @ExceptionHandler(DuplicateIdentityException.class)
188	    @ResponseBody
189	    public ResponseEntity<ProblemDetail> handleDuplicateIdentityException(DuplicateIdentityException e, HttpServletRequest request) {
190	        return conflictOrLimit(e, HttpStatus.CONFLICT, request, ERROR_DUPLICATE_IDENTITY);
191	    }
192	
193	    /**
194	     * Handles {@link CityCapacityExceededException} thrown when a request tries to create an owner
195	     * whose city already contains the maximum number of owners. Returns a 409 Conflict.
196	     *
197	     * @param e The {@link CityCapacityExceededException} to be handled
198	     * @param request {@link HttpServletRequest} object referring to the current request.
199	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
200	     */
201	    @ExceptionHandler(CityCapacityExceededException.class)
202	    @ResponseBody
203	    public ResponseEntity<ProblemDetail> handleCityCapacityExceededException(CityCapacityExceededException e, HttpServletRequest request) {
204	        return conflictOrLimit(e, HttpStatus.CONFLICT, request, ERROR_CITY_AT_CAPACITY);
205	    }
206	
207	    /**
208	     * Handles {@link DailyOwnerLimitExceededException} thrown when a request tries to create an owner
209	     * once the maximum number of owners for the current day has already been created. Returns a
210	     * 429 Too Many Requests.
211	     *
212	     * @param e The {@link DailyOwnerLimitExceededException} to be handled
213	     * @param request {@link HttpServletRequest} object referring to the current request.
214	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status.
215	     */
216	    @ExceptionHandler(DailyOwnerLimitExceededException.class)
217	    @ResponseBody
218	    public ResponseEntity<ProblemDetail> handleDailyOwnerLimitExceededException(DailyOwnerLimitExceededException e, HttpServletRequest request) {
219	        return conflictOrLimit(e, HttpStatus.TOO_MANY_REQUESTS, request, ERROR_DAILY_LIMIT_EXCEEDED);
220	    }
221	
222	    /**
223	     * Renders a create-time business-rule rejection (an owner-identity conflict or an exhausted
224	     * per-day/per-city quota) as a {@link ProblemDetail} response carrying the given status and
225	     * detail message. This is the single definition of how those rejections are logged and
226	     * rendered, shared by every handler that maps such an exception to its response.
227	     *
228	     * @param e The rejection to be handled
229	     * @param status HTTP response status the rejection maps to.
230	     * @param request {@link HttpServletRequest} object referring to the current request.
231	     * @param detailMessage the human-readable detail message for the response body.
232	     * @return A {@link ResponseEntity} containing the error information and the given status.
233	     */
234	    private ResponseEntity<ProblemDetail> conflictOrLimit(Exception e, HttpStatus status, HttpServletRequest request, String detailMessage) {
235	        logger.debug("{} at {} {}: {}",
236	            status.getReasonPhrase(),
237	            request.getMethod(),
238	            request.getRequestURI(),
239	            e.getMessage());
240	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), detailMessage);
241	        return ResponseEntity.status(status).body(detail);
242	    }
243	
